@@ -10,15 +10,16 @@ export const cart = {
   add(item) {
-    const found = this.items.find((i) => i.sku === item.sku);
-    if (found) found.qty += 1;
-    else this.items.push({ ...item, qty: 1 });
+    this.items = upsert(this.items, item);
     this.persist();
   },
   remove(sku) {
-    this.items = this.items.filter((i) => i.sku !== sku);
+    this.items = this.items.filter((i) => i.sku !== sku);
     this.persist();
   },
 };
+
+function upsert(items, item) {
+  const found = items.find((i) => i.sku === item.sku);
+  return found
+    ? items.map((i) => (i.sku === item.sku ? { ...i, qty: i.qty + 1 } : i))
+    : [...items, { ...item, qty: 1 }];
+}
